using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;
namespace MonitorSlice {
static class CarryTests {
 static void Wait(int ms){var until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}}
 static Rectangle Bounds(Form f){Native.Rect r;Native.GetWindowRect(f.Handle,out r);return r.Box;}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 [DllImport("MonitorSlice.Capture.dll",CallingConvention=CallingConvention.Cdecl)]static extern int MappedIconCount();
 public static void Run(){var records=new List<object>();var session=new VirtualSession();session.Recover();var screens=Screen.AllScreens.Where(s=>!Displays.Virtual().Any(v=>v.Name==s.DeviceName)).ToArray();WindowCarry.IncludeTestWindows=true;
 try{foreach(var screen in screens){var forms=new List<Form>();try{var target=screen.Bounds;var other=screens.First(s=>s.DeviceName!=screen.DeviceName).Bounds;var positions=new[]{new Rectangle(target.Right-440,target.Bottom-340,400,280),new Rectangle(target.Left+100,target.Top+110,550,400),new Rectangle(other.Left+50,other.Top+80,500,350)};for(int i=0;i<positions.Length;i++){var f=new Form{Text="CarryTest "+i,AutoScaleMode=AutoScaleMode.None,StartPosition=FormStartPosition.Manual};f.Show();var b=positions[i];Native.SetWindowPos(f.Handle,IntPtr.Zero,b.X,b.Y,b.Width,b.Height,0x214);forms.Add(f);}Wait(200);var before=forms.Select(f=>Bounds(f)).ToArray();session.Start(target,Layouts.Create("grid"),false);Wait(400);var first=session.Views.OrderBy(v=>v.Source.Top).ThenBy(v=>v.Source.Left).First().Source;var during=forms.Select(f=>Bounds(f)).ToArray();Check(first.Contains(during[0])&&first.Contains(during[1]),"기존 창이 첫 칸 안에 배치되지 않았습니다.");Check(during[2]==before[2],"다른 모니터 창의 위치가 달라졌습니다.");int icons=MappedIconCount();session.Stop();Wait(200);var after=forms.Select(f=>Bounds(f)).ToArray();Check(after.SequenceEqual(before),"종료 후 창 위치 복원 실패: "+string.Join(";",before.Select((b,i)=>b+" -> "+after[i])));records.Add(new{monitor=screen.DeviceName,mappedIcons=icons,selectedWindows=2,otherMonitorUnchanged=true,windowsRestored=true,passed=true});}finally{session.Stop();foreach(var f in forms)f.Close();}}}finally{WindowCarry.IncludeTestWindows=false;session.Stop();Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence"));File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","carry-test.json"),new JavaScriptSerializer().Serialize(records));}}
}
}
